<template><view class="order-create"><jk-page-nav title="创建订货单"></jk-page-nav><view class="steps"><text class="active">1 选择商品</text><text>2 确认订单</text><text>3 提交成功</text></view><view class="search"><input v-model="keyword" placeholder="搜索商品名称/规格/条码" @confirm="loadCatalog"/><text @click="loadCatalog">搜索</text></view><view v-for="item in catalog" :key="item.productId" class="product"><image :src="item.product.image" mode="aspectFill"/><view class="product-info"><strong>{{ item.product.storeName }}</strong><text>规格：{{ item.product.skuText || item.product.skuName || '-' }}</text><text class="stock">库存：{{ item.stock.visibleQty === null ? '-' : item.stock.visibleQty }}</text><b>￥{{ item.price.amount }}</b></view><view class="counter"><text @click="change(item,-1)">−</text><strong>{{ quantities[item.productId] || 0 }}</strong><text @click="change(item,1)">＋</text></view></view><view v-if="!catalog.length" class="empty">暂无可订货商品</view><view class="bottom"><view>已选 <b>{{ selectedCount }}</b> 种商品<br/>合计 <strong>￥{{ totalAmount }}</strong></view><button :disabled="!selectedCount||loading" @click="submit">下一步</button></view></view></template>
<script>import JkPageNav from '@/components/jk/jk-page-nav.vue';import {getJkProductCatalog,createJkPlatformOrder} from '@/api/jk.js';export default{components:{JkPageNav},data(){return{catalog:[],quantities:{},keyword:'',loading:false};},computed:{selected(){return this.catalog.filter(x=>this.quantities[x.productId]>0);},selectedCount(){return this.selected.length;},totalAmount(){return this.selected.reduce((n,x)=>n+Number(x.price.amount||0)*this.quantities[x.productId],0).toFixed(2);}},onLoad(){this.loadCatalog();},methods:{loadCatalog(){getJkProductCatalog(this.keyword).then(r=>{this.catalog=r.data||r||[];}).catch(e=>this.$util.Tips({title:e||'商品目录加载失败'}));},change(item,delta){let n=(this.quantities[item.productId]||0)+delta;let max=item.stock.visibleQty;if(n<0)n=0;if(max!==null&&max!==undefined&&n>max)n=max;this.$set(this.quantities,item.productId,n);},submit(){this.loading=true;let items=this.selected.map(x=>({productId:x.productId,skuId:x.skuId,quantity:this.quantities[x.productId]}));createJkPlatformOrder({requestNo:'APP'+Date.now(),items}).then(r=>{let p=r.data||r||{};this.$util.Tips({title:'订货单已提交'});if(p.id)uni.redirectTo({url:'/pages/jk/trade/detail?mode=order&id='+p.id});}).catch(e=>this.$util.Tips({title:e||'提交失败'})).finally(()=>{this.loading=false;});}}};</script>
<style lang="scss">.order-create{min-height:100vh;padding:0 28rpx 150rpx;background:#fff}.steps{display:flex;justify-content:space-between;padding:32rpx 18rpx;color:#8d96a4;font-size:26rpx}.steps .active{color:#08b996;font-weight:700}.search{display:flex;align-items:center;padding:0 22rpx;border:1rpx solid #e4e9ec;border-radius:42rpx}.search input{flex:1;height:82rpx;font-size:28rpx}.search text{color:#08ae8d}.product{display:flex;align-items:center;padding:26rpx 0;border-bottom:1rpx solid #edf0f2}.product image{width:150rpx;height:150rpx;border-radius:14rpx;background:#f4f6f7}.product-info{display:flex;flex:1;flex-direction:column;gap:9rpx;margin-left:20rpx}.product-info strong{font-size:30rpx}.product-info text{color:#7b8593;font-size:23rpx}.product-info .stock{color:#08ae8d}.product-info b{color:#ff5c3d;font-size:29rpx}.counter{display:flex;align-items:center;gap:16rpx}.counter text{display:flex;align-items:center;justify-content:center;width:50rpx;height:50rpx;border-radius:50%;background:#e2f9f3;color:#08b996;font-size:36rpx}.counter strong{min-width:32rpx;text-align:center}.bottom{position:fixed;right:0;bottom:0;left:0;display:flex;align-items:center;justify-content:space-between;padding:20rpx 30rpx calc(20rpx + env(safe-area-inset-bottom));background:#fff;box-shadow:0 -4rpx 20rpx rgba(0,0,0,.05);font-size:25rpx}.bottom b{color:#08ae8d}.bottom strong{color:#ff5c3d;font-size:34rpx}.bottom button{width:280rpx;border-radius:44rpx;background:#08b996;color:#fff}.empty{padding:100rpx 0;color:#929aa5;text-align:center}</style>
